    # Find all remaining ambiguous cells
    ambiguous = []
    for i in range(H):
        for j in range(W):
            if result[i][j] == 2:
                ambiguous.append((i, j))

    # Group ambiguous cells by their equivalence class
    seen = set()
    groups = []

    for (i, j) in ambiguous:
        if (i, j) in seen:
            continue

        group = []
        queue = [(i, j)]
        while queue:
            ci, cj = queue.pop(0)
            key = (ci, cj)
            if key in seen:
                continue
            seen.add(key)
            group.append((ci, cj))

            # Add H-mirror
            h_mirror = (ci, W - 1 - cj)
            if h_mirror not in seen and 0 <= h_mirror[0] < H and 0 <= h_mirror[1] < W:
                if result[h_mirror[0]][h_mirror[1]] == 2:
