            v_mirror = (H - 1 - ci, cj)
            if v_mirror not in seen and 0 <= v_mirror[0] < H and 0 <= v_mirror[1] < W:
                if result[v_mirror[0]][v_mirror[1]] == 2:
                    queue.append(v_mirror)

