        # For this group, find what value to use
        constraints = {}
        for ci, cj in group:
            # What does H-symmetry require?
            h_mirror = (ci, W - 1 - cj)
            if 0 <= h_mirror[0] < H and 0 <= h_mirror[1] < W:
                h_val = result[h_mirror[0]][h_mirror[1]]
                if h_val != 2:
                    if ci not in constraints:
                        constraints[ci] = []
                    constraints[ci].append((cj, h_val))

            # What does V-symmetry require?
            v_mirror = (H - 1 - ci, cj)
            if 0 <= v_mirror[0] < H and 0 <= v_mirror[1] < W:
                v_val = result[v_mirror[0]][v_mirror[1]]
                if v_val != 2:
                    if cj not in constraints:
                        constraints[cj] = []
                    constraints[cj].append((ci, v_val))

        if constraints:
            print(f"  Constraints: {constraints}")

            # Assign based on available info
            for ci, cj in group:
                val_assigned = False

                # Try to find value from constraints
                for (target_c, req_val) in constraints.get(ci, []):
                    if target_c == cj:
                        result[ci][cj] = req_val
                        val_assigned = True
                        break

                if not val_assigned:
                    # No direct constraint, try mode of nearby cells
                    neighbors = []
                    for di in [-2,-1,0,1,2]:
                        for dj in [-2,-1,0,1,2]:
